Definition fbp_exit_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (LF : list fframe) (lo shi outv n ff fp : Z) (Q : mem -> Prop) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 outv) (Z_to_bv 64 n) a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom asegs)
    /\ munch (fbp_RW ff fp) m m' /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ stk asegs m' lo (bv_unsigned sp)
    /\ Q m'
    /\ as_RFS H LF m' /\ ACONST m' /\ stack0 m' lo shi.
Scheme kc__1 := Elimination for Corelib.Init.Logic.and Sort Prop.
Scheme kc__2 := Elimination for Corelib.Init.Datatypes.bool Sort Prop.

(* [comment removed for export] *)
Lemma fbp_exit : forall (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (rax t0' t1' t2' a1' a2' a3' a4' a5' a7' t3' t4' t5' t6' xs4 xs5 xs6 xs7 xs8 xs9 xs10 : word)
    (spa lo shi ff fp outv n : Z) (LF : list fframe) (Q : mem -> Prop)
    (mx : mem) (tmp gap : list cell) (hjunk sh8 : list byte) (bflag : byte),
  rw_cells asegs mx spa tmp -> Z.of_nat (cells_size tmp) = 96 -> lo <= spa ->
  rw_cells asegs mx (spa + 96) gap -> Z.of_nat (cells_size gap) = bv_unsigned sp + -200 - spa -> spa + 96 <= bv_unsigned sp + -104 ->
  rw_cells asegs mx (bv_unsigned sp + -104) (fbp_saved s11 s10 s9 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra) ->
  rw_cells asegs mx ff [CB 56 hjunk; C8 (Z_to_bv 64 fp)] ->
  rw_cells asegs mx (Z.shiftr ff 3 + 2147450880) [CB 8 sh8] ->
  rw_cells asegs mx fp [C1 bflag] ->
  stk asegs mx lo spa -> mem_inv asegs mx ->
  as_RFS H ((0, ff, fp) :: LF) mx -> fresh_frame H LF 0 ff fp -> ACONST mx -> stack0 mx lo shi ->
  (forall m', munch (fbp_RW ff fp) mx m' -> wmono asegs mx m' -> Q m') ->
  0 <= outv < 2^64 -> 0 <= n < 2^64 ->
  aceil <= lo -> bv_unsigned ra mod 2 = 0 ->
  evt asegs (fbp_exit_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc LF lo shi outv n ff fp Q mx)
    (MS (mkR rax (Z_to_bv 64 spa) gp tp t0' t1' t2' sp (Z_to_bv 64 spa) (Z_to_bv 64 outv) a1' a2' a3' a4' a5' (Z_to_bv 64 ff) a7'
             (Z_to_bv 64 ff) (Z_to_bv 64 n) xs4 xs5 xs6 xs7 xs8 xs9 xs10 (Z_to_bv 64 (Z.shiftr ff 3 + 2147450880)) t3' t4' t5' t6')
        F (Z_to_bv 64 AFBP_EXIT) fc None mx (seg_rom asegs)).
