Definition fbp_seg1_post (sp gp tp s10 : word) (F : bvmap 5 word) (fc : bv 32) (LF : list fframe)
    (fb n lo shi : Z) (FB : fbv) (ra s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s11 : word) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t1 t2 t3 t4 t5 t6 m' (spa ff fp : Z) (gap : list cell) (tj hjunk sh8 : list byte),
    ms' = MS (mkR (Z_to_bv 64 AFBP_RET_FS) (Z_to_bv 64 spa) gp tp (Z_to_bv 64 (Z.shiftr (fb + 16) 3 + 2147450880)) t1 t2
