Lemma fbp_A : forall (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (t1' t2' t3' t4' t5' t6' : word) (LF : list fframe) (fb n lo shi spa ff fp : Z) (FB : fbv)
    (m0 mx : mem) (gap : list cell) (tj hjunk sh8 : list byte),
  (spa = bv_unsigned sp + -224 \/ spa = bv_unsigned sp + -240) ->
  stk asegs mx lo spa ->
  rw_cells asegs mx spa [CB 88 tj; C8 (Z_to_bv 64 ff)] ->
  rw_cells asegs mx (spa + 96) gap -> Z.of_nat (cells_size gap) = bv_unsigned sp + -200 - spa ->
  rw_cells asegs mx (bv_unsigned sp + -104) (fbp_saved s11 s10 s9 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra) ->
  rw_cells asegs mx ff [CB 56 hjunk; C8 (Z_to_bv 64 fp)] ->
  rw_cells asegs mx (Z.shiftr ff 3 + 2147450880) [CB 8 sh8] ->
  rw_cells asegs mx fp [C1 (b8 1)] ->
  rw_cells asegs mx fb (FlatBufCells FB) -> accessible mx fb SZ_FB -> fb mod 8 = 0 -> aplace fb SZ_FB -> (fb + SZ_FB <= lo \/ bv_unsigned sp <= fb) -> fsobj H LF fb SZ_FB ->
  fresh_frame H LF 0 ff fp -> as_RFS H ((0, ff, fp) :: LF) mx -> ACONST mx -> stack0 mx lo shi -> mem_inv asegs mx -> as_RFS H LF m0 ->
  0 <= fb_begin FB -> fb_begin FB <= fb_in FB <= fb_out FB -> fb_out FB <= fb_end FB -> fb_end FB <= aceil ->
  0 <= n -> fb_size FB + n < 2^27 -> n <= fb_end FB - fb_out FB ->
  lo + 240 <= bv_unsigned sp -> aceil <= lo -> bv_unsigned ra mod 2 = 0 ->
  evt asegs (fbp_end_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc LF (fbp_WA fb ff fp) lo shi fb (fb_out FB) n
               (mkFB (fb_begin FB) (fb_in FB) (fb_out FB) (fb_out FB + n) (fb_end FB)) mx)
    (MS (mkR (Z_to_bv 64 AFBP_RET_FS) (Z_to_bv 64 spa) gp tp (Z_to_bv 64 (Z.shiftr (fb + 16) 3 + 2147450880)) t1' t2'
                  sp (Z_to_bv 64 spa)
                  (Z_to_bv 64 (fb_out FB)) (Z_to_bv 64 (fb_in FB)) (Z_to_bv 64 (fb_end FB - fb_out FB)) (Z_to_bv 64 u64max) (Z_to_bv 64 (fb_end FB))
                  (Z_to_bv 64 (fb + 16)) (Z_to_bv 64 ff) (Z_to_bv 64 (fb + 8))
                  (Z_to_bv 64 ff) (Z_to_bv 64 n) (Z_to_bv 64 fb) (Z_to_bv 64 (Z.shiftr (fb + 8) 3 + 2147450880)) (Z_to_bv 64 2147450880)
                  (Z_to_bv 64 (fb_out FB - fb_in FB)) (Z_to_bv 64 (fb + 32)) (Z_to_bv 64 (Z.shiftr (fb + 32) 3 + 2147450880)) s10
                  (Z_to_bv 64 (Z.shiftr ff 3 + 2147450880)) t3' t4' t5' t6')
        F (Z_to_bv 64 AFBP_TA) fc None mx (seg_rom asegs)).
